import{_ as t,o,c as i,ag as a}from"./chunks/framework.CVaJrGn7.js";const g=JSON.parse('{"title":"Introduction","description":"Introduction to GuideFlow.js — an open-source product tour library for React, Vue, Svelte and Vanilla JS, where every tour is a finite state machine and the AI layer is optional.","frontmatter":{"description":"Introduction to GuideFlow.js — an open-source product tour library for React, Vue, Svelte and Vanilla JS, where every tour is a finite state machine and the AI layer is optional.","keywords":"GuideFlow introduction, product tour library overview, user onboarding JavaScript, open source tour library","head":[["link",{"rel":"canonical","href":"https://realnerdzw.github.io/GuideFlow/guide/"}],["meta",{"property":"og:url","content":"https://realnerdzw.github.io/GuideFlow/guide/"}],["meta",{"property":"og:title","content":"Introduction — GuideFlow.js"}],["meta",{"property":"og:description","content":"Introduction to GuideFlow.js — an open-source product tour library for React, Vue, Svelte and Vanilla JS, where every tour is a finite state machine and the AI layer is optional."}],["meta",{"name":"twitter:title","content":"Introduction — GuideFlow.js"}],["meta",{"name":"twitter:description","content":"Introduction to GuideFlow.js — an open-source product tour library for React, Vue, Svelte and Vanilla JS, where every tour is a finite state machine and the AI layer is optional."}],["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"BreadcrumbList\\",\\"itemListElement\\":[{\\"@type\\":\\"ListItem\\",\\"position\\":1,\\"name\\":\\"Home\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/\\"},{\\"@type\\":\\"ListItem\\",\\"position\\":2,\\"name\\":\\"Guide\\",\\"item\\":\\"https://realnerdzw.github.io/GuideFlow/guide/\\"}]}"]]},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1786207781000}'),n={name:"guide/index.md"};function r(d,e,s,l,c,u){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>GuideFlow.js is an open-source product tour library for guiding users through your application. The engine is framework-agnostic and dependency-free; the AI layer is an optional package you opt into.</p><h2 id="why-guideflow" tabindex="-1">Why GuideFlow? <a class="header-anchor" href="#why-guideflow" aria-label="Permalink to &quot;Why GuideFlow?&quot;">​</a></h2><p>Most tour libraries treat onboarding as a static linear script. GuideFlow models it as a finite state machine, so branching, guards and conditional paths are first-class rather than bolted on:</p><ul><li><strong>Tours are state machines</strong> — states, transitions and guards, with steps that can be skipped in either direction via <code>showIf</code></li><li><strong>Resumable</strong> — progress is persisted per user and per flow; completed and dismissed tours are suppressed automatically</li><li><strong>AI-generated steps</strong> — <code>gf.ai.generate()</code> serializes the page and asks your model to write the steps; you assemble them into a flow</li><li><strong>Intent detection</strong> — a classifier over recent user events emits an <code>intent:detected</code> signal you subscribe to and act on (<a href="/GuideFlow/guide/ai-intent">nothing is triggered automatically</a>)</li><li><strong>Adaptive flows</strong> — branch on role or data with <code>showIf</code> and FSM transitions</li><li><strong>Analytics</strong> — six tour lifecycle events to PostHog, Mixpanel, Amplitude, Segment or a webhook, with consent and URL-scrubbing defaults, plus <a href="/GuideFlow/guide/ab-testing">deterministic A/B assignment you apply yourself</a></li><li><strong>DevTools extension</strong> — an MV3 extension lives in the repo for inspecting a page&#39;s tour state and recording steps. It is <strong>not published</strong> to any store or to npm: build it and load it unpacked</li></ul><h2 id="packages" tabindex="-1">Packages <a class="header-anchor" href="#packages" aria-label="Permalink to &quot;Packages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Package</th><th>Description</th></tr></thead><tbody><tr><td><code>@guideflow/core</code></td><td>Framework-agnostic engine, zero runtime dependencies</td></tr><tr><td><code>@guideflow/react</code></td><td>React 17/18/19 hooks and components</td></tr><tr><td><code>@guideflow/vue</code></td><td>Vue 3 plugin and <code>useTour</code> composable</td></tr><tr><td><code>@guideflow/svelte</code></td><td>Svelte 4/5 <code>createTourStore</code></td></tr><tr><td><code>@guideflow/ai</code></td><td><code>GuideBrain</code> plus Proxy / OpenAI / Anthropic / Ollama / Mock providers</td></tr><tr><td><code>@guideflow/analytics</code></td><td>Event collection, 5 transports, A/B testing</td></tr><tr><td><code>@guideflow/cli</code></td><td><code>guideflow init / export / validate</code></td></tr><tr><td><code>@guideflow/devtools</code></td><td>Manifest V3 browser extension — <strong>not published</strong>; load it unpacked from the repo</td></tr></tbody></table><h2 id="design-principles" tabindex="-1">Design Principles <a class="header-anchor" href="#design-principles" aria-label="Permalink to &quot;Design Principles&quot;">​</a></h2><ol><li><strong>Zero dependencies in core</strong> — <code>@guideflow/core</code> has no runtime dependencies, and its gzipped bundle size is gated in CI</li><li><strong>SSR safe</strong> — DOM access is guarded and never runs at module scope, so the package can be imported from Next.js, Nuxt and SvelteKit</li><li><strong>CSP friendly</strong> — injected <code>&lt;style&gt;</code> tags accept a nonce, and <code>content.html</code> is parsed and allowlist-sanitised rather than trusted</li><li><strong>Tree-shakeable</strong> — ESM-first, <code>sideEffects: false</code>; only import what you use</li><li><strong>Type-safe</strong> — strict TypeScript, with your flow context threaded through <code>createGuideFlow&lt;TContext&gt;()</code> into guards and <code>showIf</code></li></ol><p>Start with <a href="/GuideFlow/guide/installation">Installation</a>, then the <a href="/GuideFlow/guide/quick-start">Quick Start</a>.</p>',10)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
